// Create the style for the detail section
StyleBuilder sb = new StyleBuilder();
sb.setName("detail");

// Create the conditional style
Style conditionalStyle = sb.build();

// Create the style to be applied when the condition is true
sb.setName("conditional-detail");
sb.setStyleProperty(JRStyle.PROPERTY_FONT_BOLD, "true");
Style conditionalBoldStyle = sb.build();

// Create the conditional expression, it will be applied to the column
// when the report is generated
ConditionalStyle cs = new ConditionalStyle();
cs.setCondition(new ConditionStyleExpression() {
    public Object evaluate(Object value) throws Exception {
        Double d = (Double) value;
        if (d != null && d.doubleValue() > 100) {
            return Boolean.TRUE;
        } else {
            return Boolean.FALSE;
        }
    }
});
cs.setStyle(conditionalBoldStyle);

// Add the conditional style to the column
dcb.addConditionalStyle(cs);

dcb.addConditionalStyle("condition-amount-greater-than-100",
    new ConditionStyleExpression() {
        public Object evaluate(Object value) throws Exception {
            Double d = (Double) value;
            if (d != null && d.doubleValue() > 100) {
                return Boolean.TRUE;
            } else {
                return Boolean.FALSE;
            }
        }
    });

/*
 * Add a first-page image banner (header of the report).
 */
drb.addFirstPageImageBanner("images/logo_fdv_solutions_60.png", 197, 60, ImageBanner.Alignment.Left)
   .addFirstPageImageBanner("images/dynamicJasper_60.jpg", 300, 60, ImageBanner.Alignment.Right);

/*
 * Add an image banner to all pages.
 */
drb.addImageBanner("images/logo_fdv_solutions_60.png", 100, 25, ImageBanner.Alignment.Left, ImageScaleMode.FILL)
   .addImageBanner("images/dynamicJasper_60.jpg", 150, 25, ImageBanner.Alignment.Right, ImageScaleMode.FILL);

/*
 * Set the template to be used to generate the report.
 */
String templatePath = "template.xml";
drb.addTemplate(templatePath);

/*
 * Add the report header text.
 */
drb.addReportHeader("This is the report header");

/*
 * Add the report footer text.
 */
drb.addReportFooter("This is the report footer");

/*
 * Set the chart type and style.
 */
DJChart chart = new DJChart();
chart.setType(DJChartConstants.CHART_TYPE_BAR);
chart.setTitle("State chart");

/*
 * Add the column that will be used in the chart.
 */
DJVariable chartColumn = new DJVariable("state", "state", String.class.getName());
chartColumn.setOperation(DJVariable.OPERATION_NONE);
chart.addGroupByColumn(chartColumn);

/*
 * Add the data to be used in the chart.
 */
DJVariable chartData = new DJVariable("amount", "amount", Float.class.getName());
chartData.setOperation(DJVariable.OPERATION_SUM);
chart.addGroupColumnValue(chartData);

/*
 * Add the chart to the report.
 */
drb.addChart(chart);

/*
 * Set the chart parameters.
 */
chart.setParameter(DJChartConstants.PARAMETER_DATA_SET_KEY, "chart-data");
chart.setParameter(DJChartConstants.PARAMETER_DATA_SET_FIELD_LABEL, "state");
chart.setParameter(DJChartConstants.PARAMETER_DATA_SET_FIELD_VALUE, "amount");
chart.setParameter(DJChartConstants.PARAMETER_DATA_SET_GROUP, "state");

/*
 * Create the report.
 */
FastReportBuilder drb = new FastReportBuilder();

/*
 * Create the column.
 */
ColumnBuilder dcb = new ColumnBuilder();
dcb.setName("Amount");
dcb.setProperty("amount");
dcb.setType(Float.class.getName());
dcb.setWidth(50);

/*
 * Create the group.
 */
GroupBuilder gb = new GroupBuilder();
gb.setName("state");
gb.setProperty("state");
gb.setType(String.class.getName());
gb.setLayout(GroupLayout.GROUP_HEADER);
drb.addGroup(gb);

/*
 * Create the custom expression.
 */
CustomExpression customExpression = new CustomExpression() {
    public Object evaluate(Object value) throws Exception {
        // Format the value
        return "Total: " + value;
    }
};

/*
 * Create the custom column.
 */
dcb.setCustomExpression(customExpression);
drb.addColumn(dcb.build());

/*
 * Add the group total column to the report.
 */
gb.addFooterVariable("amount-total", DJVariable.OPERATION_SUM);

/*
 * Set the auto-text field.
 */
drb.setAutoText("Today's date: " + AutoTextConstants.DATE);

public class ReportAction extends Action {

    public void run() throws Exception {
        // Get the report from the request
        DynamicReport report = (DynamicReport) context.get("report");

        // Get the data source from the request
        DataSource ds = (DataSource) context.get("dataSource");

        // Generate the report
        JasperPrint print = DynamicJasperHelper.generateJasperPrint(report, ds);

        // Export the report to a PDF
        JRPdfExporter exporter = new JRPdfExporter();
        exporter.setParameter(JRExporterParameter.OUTPUT_STREAM, getResponse().getOutputStream());
        exporter.setParameter(JRExporterParameter.JASPER_PRINT, print);
        exporter.exportReport();
    }
}

/*
 * Set the subreport to be used in the report.
 */
String subreportPath = "subreport.jasper";
drb.addSubreport("subreport", subreportPath);

/*
 * Create the subreport parameters.
 */
Map subreportParameters = new HashMap();
subreportParameters.put("parameter1", "value1");
subreportParameters.put("parameter2", "value2");

/*
 * Add the subreport to the report.
 */
drb.addSubreportData("subreport-data", subreportParameters);
